# Create an encrypted backup vault
aws backup create-backup-vault \
  --backup-vault-name my-backup-vault \
  --encryption-key-arn arn:aws:kms:us-east-1:123456789012:key/12345678-1234-1234-1234-123456789012

# Create a backup plan
aws backup create-backup-plan \
  --backup-plan '{
    "BackupPlanName": "daily-backup-plan",
    "Rules": [
      {
        "RuleName": "daily-backup",
        "TargetBackupVaultName": "my-backup-vault",
        "ScheduleExpression": "cron(0 12 * * ? *)",
        "StartWindowMinutes": 60,
        "Lifecycle": {
          "DeleteAfter": 30,
          "MoveToColdStorageAfter": 7
        }
      }
    ]
  }'
